'use strict';
const express=require('express'),fs=require('fs'),path=require('path'),crypto=require('crypto'),sharp=require('../../vendor/upscale/node_modules/sharp'),{db}=require('./db'),{DATA_DIR}=require('./paths');const router=express.Router(),hash=s=>crypto.createHash('sha256').update(s).digest('hex').slice(0,20);
function refFile(tag){const r=db.prepare('SELECT * FROM ref_images WHERE tag=? AND archived_at IS NULL').get(String(tag||''));if(!r||!fs.existsSync(r.filepath))throw Error('Ảnh storyboard không còn trong thư viện');const real=fs.realpathSync(r.filepath),allowed=['uploads','videos'].map(d=>path.join(DATA_DIR,d));if(!allowed.some(d=>real.startsWith(fs.realpathSync(d)+path.sep)))throw Error('Ảnh nằm ngoài dữ liệu ứng dụng');return real}
function analyzeAxis(data,w,h,axis){const n=axis==='x'?w:h,m=axis==='x'?h:w,profile=[];for(let i=0;i<n;i++){let sum=0,sq=0;for(let j=0;j<m;j++){const v=data[axis==='x'?j*w+i:i*w+j];sum+=v;sq+=v*v}const mean=sum/m,std=Math.sqrt(Math.max(0,sq/m-mean*mean));profile.push((1-Math.min(1,std/70))*.7+Math.abs(mean-127.5)/127.5*.3)}let best={count:1,score:0};for(let count=2;count<=8;count++){let sum=0,min=1;for(let k=1;k<count;k++){const mid=k*n/count,r=Math.max(2,Math.round(n*.025));let peak=0;for(let t=Math.max(1,Math.floor(mid-r));t<Math.min(n-1,mid+r);t++)peak=Math.max(peak,profile[t]);let neighbors=0,num=0;for(let t=Math.max(0,Math.floor(mid-n/count*.36));t<Math.min(n,mid+n/count*.36);t++)if(Math.abs(t-mid)>r){neighbors+=profile[t];num++}const score=Math.max(0,(peak-(num?neighbors/num:0)))*Math.min(1,peak/.8);sum+=score;min=Math.min(min,score)}const score=(sum/(count-1))*.5+min*.5;if(score>best.score+.025)best={count,score}}return best}
async function detectGrid(file){const raw=await sharp(file,{limitInputPixels:50000000}).rotate().resize({width:640,height:640,fit:'inside',withoutEnlargement:true}).flatten({background:'#ffffff'}).greyscale().raw().toBuffer({resolveWithObject:true}),x=analyzeAxis(raw.data,raw.info.width,raw.info.height,'x'),y=analyzeAxis(raw.data,raw.info.width,raw.info.height,'y');const clearX=x.score>.15,clearY=y.score>.15;return {columns:clearX?x.count:clearY?1:3,rows:clearY?y.count:clearX?1:2,confidence:clearX||clearY?Math.min(1,Math.max(x.score,y.score)*2):0,warning:clearX||clearY?'Lưới được đề xuất từ đường phân cách. Kiểm tra lại toàn bộ khung trước khi dựng.':'Chưa nhận rõ đường chia ô. Đang gợi ý lưới 3 × 2; chỉnh hàng/cột và tách lại nếu cần.'}}
async function extractFrames(body){const file=refFile(body.refTag),detected=await detectGrid(file),rows=body.rows===undefined?detected.rows:Number(body.rows),columns=body.columns===undefined?detected.columns:Number(body.columns),inset=Number(body.inset||0);if(!Number.isInteger(rows)||!Number.isInteger(columns)||rows<1||rows>8||columns<1||columns>8||!Number.isFinite(inset)||inset<0||inset>12)throw Error('Lưới từ 1–8 hàng/cột, viền cắt từ 0–12%');const normalized=await sharp(file,{limitInputPixels:50000000}).rotate().png().toBuffer({resolveWithObject:true}),{width,height}=normalized.info;if(width<columns*32||height<rows*32)throw Error('Storyboard quá nhỏ để tách số khung này');const digest=hash(normalized.data),items=[],dir=path.join(DATA_DIR,'uploads');fs.mkdirSync(dir,{recursive:true});for(let row=0;row<rows;row++)for(let col=0;col<columns;col++){const index=items.length,l=Math.floor(col*width/columns),t=Math.floor(row*height/rows),right=Math.floor((col+1)*width/columns),bottom=Math.floor((row+1)*height/rows),dx=Math.floor((right-l)*inset/100),dy=Math.floor((bottom-t)*inset/100),w=right-l-2*dx,h=bottom-t-2*dy,key=hash(digest+':'+rows+':'+columns+':'+inset+':'+index),tag='space_'+key,filename='frame_'+key+'.png',target=path.join(dir,filename);if(!fs.existsSync(target)){const tmp=target+'.tmp';await sharp(normalized.data).extract({left:l+dx,top:t+dy,width:w,height:h}).png().toFile(tmp);fs.renameSync(tmp,target)}if(fs.statSync(target).size>8*1024*1024)throw Error('Khung '+(index+1)+' vượt 8 MB; chọn lưới nhỏ hơn mỗi khung hoặc giảm kích thước ảnh nguồn trước khi dựng');const prior=db.prepare('SELECT id FROM ref_images WHERE tag=?').get(tag);if(!prior)db.prepare("INSERT INTO ref_images(id,tag,filename,filepath,size,mime_type,internal_only,created_at) VALUES(?,?,?,?,?,'image/png',0,datetime('now'))").run(crypto.randomUUID(),tag,filename,target,fs.statSync(target).size);else db.prepare('UPDATE ref_images SET archived_at=NULL WHERE tag=?').run(tag);items.push({tag,url:'/uploads/'+filename,width:w,height:h,index:index+1,label:'Khung '+String(index+1).padStart(2,'0'),enabled:true,motion:''})}require('./referenceLibrary').publishRefs();return {items,rows,columns,inset,sourceTag:body.refTag,width,height,detected}}
router.get('/capabilities',(_req,res)=>res.json({ready:true,version:2,gridMax:8,durations:[3,5,7,8,10],modes:["text","image","frames","whole","multishot"],frameControl:"reference",multishot:"separate-clips"}));
let extracting=false;router.post('/frames',async(req,res)=>{if(extracting)return res.status(429).json({error:'Đang tách storyboard khác. Hãy chờ hoàn tất.'});extracting=true;try{res.json(await extractFrames(req.body||{}))}catch(e){res.status(422).json({error:e.message})}finally{extracting=false}});module.exports={router,detectGrid,extractFrames,analyzeAxis};
